package org.dromara.property.charge.rule.mysql;
import org.junit.jupiter.api.*; import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable; import java.sql.*; import java.time.LocalDate; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="ZBM_TEST_DB_URL",matches=".+") class ChargeRuleMySqlTest {
 Connection c; long p1,p2,i1,i2;
 @BeforeEach void setUp() throws Exception{c=DriverManager.getConnection(System.getenv("ZBM_TEST_DB_URL"),System.getenv("ZBM_TEST_DB_USER"),System.getenv("ZBM_TEST_DB_PASSWORD"));assertEquals("zbm_property_test",c.getCatalog());p1=id();p2=id();i1=id();i2=id();project(p1);project(p2);item(i1,p1,"PERIODIC");item(i2,p2,"PERIODIC");}
 @AfterEach void clean() throws Exception{if(c==null)return;try(Statement s=c.createStatement()){s.executeUpdate("DELETE FROM pm_charge_rule WHERE project_id IN ("+p1+","+p2+")");s.executeUpdate("DELETE FROM pm_charge_item WHERE project_id IN ("+p1+","+p2+")");s.executeUpdate("DELETE FROM pm_project WHERE id IN ("+p1+","+p2+")");}c.close();}
 @Test void activeCodeUniquePerProjectAndReusableAfterLogicalDelete() throws Exception{rule(id(),p1,i1,"R", "0","AREA",1,null);assertThrows(SQLException.class,()->rule(id(),p1,i1,"R","0","AREA",1,null));rule(id(),p2,i2,"R","0","AREA",1,null);try(PreparedStatement s=c.prepareStatement("UPDATE pm_charge_rule SET del_flag='1' WHERE project_id=?")){s.setLong(1,p1);s.executeUpdate();}assertDoesNotThrow(()->rule(id(),p1,i1,"R","0","AREA",1,null));}
 @Test void amountAndDateChecksAreEnforced() throws Exception{assertThrows(SQLException.class,()->rule(id(),p1,i1,"BAD1","0","AREA",1,2));assertThrows(SQLException.class,()->rule(id(),p1,i1,"BAD2","0","FIXED",null,null));try(PreparedStatement s=c.prepareStatement("INSERT INTO pm_charge_rule(id,project_id,charge_item_id,rule_code,rule_name,billing_method,billing_cycle,cycle_mode,fixed_amount,effective_start_date,effective_end_date,status,sort,del_flag) VALUES(?,?,?,?,?,'FIXED','MONTH','NATURAL',1,?,?,'0',0,'0')")){s.setLong(1,id());s.setLong(2,p1);s.setLong(3,i1);s.setString(4,"BAD3");s.setString(5,"BAD3");s.setDate(6,Date.valueOf(LocalDate.now()));s.setDate(7,Date.valueOf(LocalDate.now().minusDays(1)));assertThrows(SQLException.class,s::executeUpdate);}}
 @Test void currentEffectiveOptionsPredicateHasExpectedRows() throws Exception{rule(id(),p1,i1,"NOW","0","FIXED",null,10);rule(id(),p1,i1,"OFF","1","FIXED",null,10);try(PreparedStatement s=c.prepareStatement("SELECT COUNT(*) FROM pm_charge_rule WHERE project_id=? AND status='0' AND effective_start_date<=CURRENT_DATE AND (effective_end_date IS NULL OR effective_end_date>=CURRENT_DATE) AND del_flag='0'")){s.setLong(1,p1);try(ResultSet r=s.executeQuery()){assertTrue(r.next());assertEquals(1,r.getInt(1));}}}
 void project(long id)throws Exception{try(PreparedStatement s=c.prepareStatement("INSERT INTO pm_project(id,project_code,project_name,sort,status,del_flag)VALUES(?,?,?,0,'0','0')")){s.setLong(1,id);s.setString(2,"P"+id);s.setString(3,"P"+id);s.executeUpdate();}} void item(long id,long p,String type)throws Exception{try(PreparedStatement s=c.prepareStatement("INSERT INTO pm_charge_item(id,project_id,item_code,item_name,charge_type,charge_category,charge_object_type,status,sort,del_flag)VALUES(?,?,?,?,?,'PROPERTY_FEE','ROOM','0',0,'0')")){s.setLong(1,id);s.setLong(2,p);s.setString(3,"I"+id);s.setString(4,"I"+id);s.setString(5,type);s.executeUpdate();}}
 void rule(long id,long p,long item,String code,String del,String method,Integer unit,Integer fixed)throws Exception{try(PreparedStatement s=c.prepareStatement("INSERT INTO pm_charge_rule(id,project_id,charge_item_id,rule_code,rule_name,billing_method,billing_cycle,cycle_mode,unit_price,fixed_amount,effective_start_date,status,sort,del_flag)VALUES(?,?,?,?,?,?,'MONTH','NATURAL',?,?,CURRENT_DATE,'0',0,?)")){s.setLong(1,id);s.setLong(2,p);s.setLong(3,item);s.setString(4,code);s.setString(5,code);s.setString(6,method);if(unit==null)s.setNull(7,Types.DECIMAL);else s.setInt(7,unit);if(fixed==null)s.setNull(8,Types.DECIMAL);else s.setInt(8,fixed);s.setString(9,del);s.executeUpdate();}} static long id(){return Math.abs(UUID.randomUUID().getMostSignificantBits()>>>1);}
}
